import { Component, h, Prop, Host, ComponentInterface, Element } from '@stencil/core';
import classNames from 'classnames';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'empty-state';

/**
 * @slot illustration - Allows customization of the illustration area.
 * @slot title - Allows customization of the title content.
 * @slot description - Allows customization of the description content. If provided, this content will be used instead of the `description` prop.
 * @slot footer - Allows customization of the footer content (Previously CTA action area).
 * @part base - The base container of the component.
 * @part inner - The inner layout wrapper that centers the empty state content.
 * @part illustration - The illustration container.
 * @part title - The title element.
 * @part description - The description element.
 * @part footer - The footer container.
 */
@Component({
  tag: 'ks-empty-state',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsEmptyState implements ComponentInterface {
  @Element() el?: HTMLKsEmptyStateElement;

  /** The size of the empty state component. Possible values are `"lg"`, `"md"` and `"sm"`. */
  @Prop() size: 'md' | 'sm' | 'lg' = 'md';
  /** The title displayed in the empty state header. */
  @Prop() title = '';

  /** A description displayed in the empty state, providing more context or information. */
  @Prop() description?: string;
  /** Indicates whether to show the illustration in the empty state. When `true`, the illustration is displayed. */
  @Prop() showIllustration = true;
  /**
   * Indicates whether the empty state should be automatically centered within its container. This can be a boolean value or the string `fixed`.
   * When `true`, the component is centered.
   * When `fixed`, the component is centered with fixed positioning.
   */
  @Prop() autoCenter: boolean | 'fixed' = false;
  /** The component slot that display in the footer area */
  @Slot({ slotname: 'footer' }) private footer?: Slots;

  render() {
    return (
      <Host class="KsEmptyState" ks-auto-center={String(this.autoCenter || false)}>
        <div part="base" class={classNames(prefix)}>
          <div part="inner" class={classNames(`${prefix}-inner`, `${prefix}--${this.size}`)}>
            {this.showIllustration && (
              <div class={classNames(`${prefix}__illustration`, this.size)} part="illustration">
                <slot name="illustration">
                  <div class="default-illustration" />
                </slot>
              </div>
            )}
            <div class={`${prefix}__title`} part="title">
              <slot name="title">{this.title}</slot>
            </div>
            <div class={`${prefix}__description`} part="description">
              <slot name="description">{this.description}</slot>
            </div>
            {this.footer && (
              <div class={`${prefix}__footer`} part="footer">
                <slot name="footer"></slot>
              </div>
            )}
          </div>
        </div>
      </Host>
    );
  }
}
